import "dotenv/config";
import express from "express";
import cors from "cors";
import cookieParser from "cookie-parser";

import { authRouter, courseRouter } from "./routes/index.js";
import { errorHandler } from "./middlewares/index.js";

// Create Express app
const app = express();

// Global Middlewares
app.use(cors());
app.use(express.json());
app.use(cookieParser());

// Routes
app.use("/auth", authRouter); // Authentication routes
app.use("/courses", courseRouter); // Courses routes

// error handling middleware
app.use(errorHandler);

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is listening on port ${PORT}...`);
});

import express from "express";

const router = express.Router();

import { authentication } from "../middlewares/index.js";
import { getAllCourses } from "../controllers/index.js";

router.route("/").get(authentication, getAllCourses);

export default router;

import { cerbosService } from "../service/index.js";

import { Courses } from "../db/data.js";

const getAllCourses = async (req, res) => {
  try {
    const principal = req.user;

    // authorization check for each course
    const authorizedCourses = await Promise.all(
      Courses.map(async (course) => {
        const isAuthorized = await cerbosService.isAuthorized(
          principal,
          course,
          "view",
        );
        return isAuthorized ? course : null;
      }),
    );

    res.status(200).json({
      courses: authorizedCourses.filter(Boolean),
      message: "Courses fetched successfully",
    });
  } catch (error) {
    console.error("Error fetching courses:", error);
  }
};

export { getAllCourses };

export default (err, req, res, next) => {
  console.error(err?.message);
  res.status(500).json(err?.message || "Something failed");
};

import authRouter from "./auth.route.js";
import courseRouter from "./course.route.js";

export { authRouter, courseRouter };

import { HTTP as Cerbos } from "@cerbos/http";

const cerbos = new Cerbos(process.env.CERBOS_PDP_URL);

const isAuthorized = async (principal, resource, action) => {
  try {
    const check = await cerbos.checkResource({
      principal: {
        id: `${principal?.id}`,
        roles: principal?.roles,
      },
      resource: {
        kind: "course",
        id: resource.id,
        attr: JSON.parse(JSON.stringify(resource)),
      },
      actions: [action],
    });
    return check.isAllowed(action);
  } catch (error) {
    console.error(
      `Error checking ${action} authorization for resource:`,
      error,
    );
    throw new Error(`Authorization check failed for ${action} on resource`);
  }
};

export const cerbosService = {
  isAuthorized,
};

